"""Proton Updater for Steam: downloads new Proton versions and switches chosen games.

Commands:
  protonupd.py run            — for the timer: apply pending + check for new versions every 12 h
  protonupd.py check          — check for new versions now (and install)
  protonupd.py status         — show games and versions
  protonupd.py restart        — restart Steam and apply pending switches
  protonupd.py auto on|off [APPID] — switch automatic updates (all, or one game)
  protonupd.py version        — show the version and whether a newer Proton Updater exists
  protonupd.py selfupdate     — update Proton Updater itself
  protonupd.py install SRC TAG — install a specific version
  protonupd.py set APPID SRC [TAG] — bind a game to a source (and version)
"""
from i18n import S, set_lang, tr
from version import APP_REPO, VERSION
import hashlib, json, os, re, shutil, subprocess, sys, tarfile, tempfile, time, urllib.error, urllib.request
from pathlib import Path

STEAM = Path.home() / ".local/share/Steam"
COMPAT = STEAM / "compatibilitytools.d"
CFG_VDF = STEAM / "config/config.vdf"
CONF = Path.home() / ".config/proton-updater/config.json"

# Sources: repo, asset-name pattern, how to derive Steam's internal tool name from the tag
SOURCES = {
    "ge": {
        "title": "src_ge",
        "repo": "GloriousEggroll/proton-ge-custom",
        "asset": r"^(GE-Proton[\d\-]+)-x86_64\.tar\.gz$",
        "name": lambda tag: f"{tag}-x86_64",
        "match": r"^GE-Proton\d+-\d+-x86_64$",
    },
    "rtsp": {
        "title": "src_rtsp",
        "repo": "SpookySkeletons/proton-ge-rtsp",
        "asset": r"^(proton-rtsp-[\w.\-]+)\.tar\.gz$",
        "name": lambda tag: tag,
        "match": r"^proton-rtsp-",
    },
}
DEFAULT = {"games": {"438100": {"name": "VRChat", "source": "ge", "pin": None}},
           "keep": 2, "last_check": 0, "pending": {}, "lang": "auto", "custom": {}, "bell": {}, "notified_app": "", "auto_global": True}
NAMES = CONF.parent / "installed.json"   # archive url -> {dir, tool, src} (needed for custom sources)
REPO_RE = re.compile(r"^[A-Za-z0-9_.\-]+/[A-Za-z0-9_.\-]+$")


def custom_source(cs):
    return {"title": cs["title"], "repo": cs["repo"], "custom": True, "match": None}


def src_title(key):
    t = SOURCES[key]["title"]
    return tr(t) if t in S else t


def load():
    try:
        c = json.loads(CONF.read_text())
    except Exception:
        c = {}
    for k, v in DEFAULT.items():
        c.setdefault(k, json.loads(json.dumps(v)))
    set_lang(c["lang"])
    for k in [k for k in SOURCES if SOURCES[k].get("custom")]:
        del SOURCES[k]
    for k, cs in c["custom"].items():
        SOURCES[k] = custom_source(cs)
    return c


def names():
    try:
        return json.loads(NAMES.read_text())
    except Exception:
        return {}


def add_custom(c, repo, title=""):
    """Register a GitHub repo as a Proton source (after checking that it has usable releases)."""
    repo = repo.strip().removeprefix("https://github.com/").strip("/")
    if not REPO_RE.match(repo):
        raise RuntimeError(tr("custom_bad"))
    key = "c_" + re.sub(r"\W", "_", repo)
    SOURCES[key] = custom_source({"title": title or repo, "repo": repo})
    try:
        if not releases(key, 10):
            raise RuntimeError(tr("custom_none"))
    except Exception:
        del SOURCES[key]
        raise
    c["custom"][key] = {"title": title or repo, "repo": repo}
    save(c)
    return key


def remove_custom(c, key):
    c["custom"].pop(key, None)
    SOURCES.pop(key, None)
    for a in [a for a, g in c["games"].items() if g["source"] == key]:
        c["games"].pop(a); c["pending"].pop(a, None)
    save(c)


def save(c):
    CONF.parent.mkdir(parents=True, exist_ok=True)
    CONF.write_text(json.dumps(c, ensure_ascii=False, indent=1))


CACHE = Path.home() / ".cache/proton-updater"
CACHE_TTL = 600   # seconds: reuse a fresh answer without asking GitHub at all


def http_json(url):
    """GitHub API call with a disk cache + ETag (a 304 answer does not count against the rate limit)."""
    CACHE.mkdir(parents=True, exist_ok=True)
    f = CACHE / (hashlib.sha1(url.encode()).hexdigest() + ".json")
    cached = None
    try:
        cached = json.loads(f.read_text())
        if time.time() - cached["t"] < CACHE_TTL:
            return cached["body"]
    except Exception:
        cached = None
    headers = {"User-Agent": "proton-updater", "Accept": "application/vnd.github+json"}
    if os.environ.get("GITHUB_TOKEN"):
        headers["Authorization"] = "Bearer " + os.environ["GITHUB_TOKEN"]
    if cached and cached.get("etag"):
        headers["If-None-Match"] = cached["etag"]
    try:
        with urllib.request.urlopen(urllib.request.Request(url, headers=headers), timeout=30) as r:
            body = json.load(r)
            f.write_text(json.dumps({"t": time.time(), "etag": r.headers.get("ETag"), "body": body}))
            return body
    except urllib.error.HTTPError as e:
        if e.code == 304 and cached:
            cached["t"] = time.time(); f.write_text(json.dumps(cached))
            return cached["body"]
        if e.code in (403, 429):
            if cached:
                return cached["body"]          # better stale than nothing
            reset = e.headers.get("x-ratelimit-reset")
            when = time.strftime("%H:%M", time.localtime(int(reset))) if reset else "?"
            raise RuntimeError(tr("rate_limit", t=when))
        raise
    except urllib.error.URLError:
        if cached:
            return cached["body"]              # offline: use the last known answer
        raise


def releases(src, n=30):
    s = SOURCES[src]
    out = []
    for r in http_json(f"https://api.github.com/repos/{s['repo']}/releases?per_page={n}"):
        if r.get("prerelease") or r.get("draft"):
            continue
        if s.get("custom"):
            rel = generic_release(r)
            if rel:
                out.append(rel)
            continue
        for a in r["assets"]:
            m = re.match(s["asset"], a["name"])
            if m:
                sha = next((x["browser_download_url"] for x in r["assets"] if x["name"] == a["name"] + ".sha512sum"
                            or x["name"] == a["name"][:-7] + ".sha512sum"), None)
                out.append({"tag": r["tag_name"], "name": s["name"](m.group(1)), "url": a["browser_download_url"],
                            "sha": sha, "algo": "sha512", "page": r["html_url"], "date": r["published_at"][:10], "size": a["size"]})
                break
    return out


ARCHIVE_EXT = (".tar.gz", ".tgz", ".tar.xz", ".tar.zst", ".tar.bz2")


def generic_release(r):
    """Pick the Linux x86_64 tarball of a release of an arbitrary Proton repo."""
    best = None
    for a in r["assets"]:
        n = a["name"].lower()
        ext = next((e for e in ARCHIVE_EXT if n.endswith(e)), None)
        if not ext or re.search(r"aarch64|arm64|armv|i686|win(32|64)|\.sha", n):
            continue
        score = 2 if re.search(r"x86[_-]64|amd64|x64", n) else 1
        if not best or score > best[0]:
            best = (score, a, ext)
    if not best:
        return None
    a = best[1]
    base = a["name"][:-len(best[2])]
    sha = algo = None
    for al in ("sha512", "sha256"):
        for cand in (a["name"] + "." + al + "sum", base + "." + al + "sum", a["name"] + "." + al):
            x = next((x for x in r["assets"] if x["name"] == cand), None)
            if x:
                sha, algo = x["browser_download_url"], al
                break
        if sha:
            break
    return {"tag": r["tag_name"], "name": base, "url": a["browser_download_url"], "sha": sha, "algo": algo,
            "page": r["html_url"], "date": r["published_at"][:10], "size": a["size"]}


def installed(src=None):
    res = []
    for d in sorted(COMPAT.glob("*")):
        for k, s in SOURCES.items():
            if s["match"] and (src in (None, k)) and re.match(s["match"], d.name):
                res.append((k, d.name))
    return res


def internal_name(d):
    """The tool name Steam uses = first key inside compat_tools of compatibilitytool.vdf."""
    try:
        m = re.search(r'"compat_tools"\s*\{\s*"([^"]+)"', (d / "compatibilitytool.vdf").read_text(errors="ignore"))
        return m.group(1) if m else None
    except OSError:
        return None


def install(rel, log=print, src=None):
    """Download, verify and unpack a release. Returns the tool name to give Steam."""
    known = names().get(rel["url"])
    if known and (COMPAT / known["dir"]).exists():
        return known["tool"]
    if not src and (COMPAT / rel["name"]).exists():
        return rel["name"]
    COMPAT.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(dir=COMPAT.parent) as tmp:
        tmp = Path(tmp)
        f = tmp / "a.tar"
        log(tr("dl", name=rel["name"], mb=rel["size"] // 1048576))
        req = urllib.request.Request(rel["url"], headers={"User-Agent": "proton-updater"})
        h = hashlib.new(rel.get("algo") or "sha512")
        with urllib.request.urlopen(req, timeout=60) as r, open(f, "wb") as o:
            while chunk := r.read(1 << 20):
                o.write(chunk); h.update(chunk)
        if rel["sha"]:
            want = urllib.request.urlopen(urllib.request.Request(rel["sha"], headers={"User-Agent": "proton-updater"}),
                                          timeout=30).read().split()[0].decode()
            if want != h.hexdigest():
                raise RuntimeError(tr("sha_bad"))
            log(tr("sha_ok"))
        else:
            log(tr("sha_none"))
        ex = tmp / "x"; ex.mkdir()
        with tarfile.open(f) as t:
            t.extractall(ex, filter="data")
        top = [p for p in ex.iterdir() if p.is_dir()]
        if len(top) != 1:
            raise RuntimeError(tr("bad_archive"))
        if src:                                   # custom source: keep the author's folder name
            dest = COMPAT / top[0].name
            tool = internal_name(top[0])
            if not tool:
                raise RuntimeError(tr("custom_notool"))
            if dest.exists():
                shutil.rmtree(dest)
        else:
            dest, tool = COMPAT / rel["name"], rel["name"]
        shutil.move(str(top[0]), str(dest))
    if src:
        nm = names(); nm[rel["url"]] = {"dir": dest.name, "tool": tool, "src": src}
        NAMES.parent.mkdir(parents=True, exist_ok=True); NAMES.write_text(json.dumps(nm, indent=1))
    log(tr("installed", name=tool))
    return tool


# ---------- Steam config.vdf ----------
def steam_running():
    return subprocess.run(["pgrep", "-x", "steam"], capture_output=True).returncode == 0


def current_tool(appid):
    t = CFG_VDF.read_text(encoding="utf-8")
    i = t.find('"CompatToolMapping"')
    m = re.compile(r'"%s"\s*\{\s*"name"\s*"([^"]*)"' % appid).search(t, i) if i >= 0 else None
    return m.group(1) if m else None


def set_tool(appid, tool):
    if steam_running():
        raise RuntimeError(tr("steam_running"))
    t = CFG_VDF.read_text(encoding="utf-8")
    i = t.find('"CompatToolMapping"')
    if i < 0:
        # Steam only writes this section once some game got a compatibility tool picked by hand;
        # create it inside Software/Valve/Steam
        m = re.search(r'"Software"\s*\{\s*"Valve"\s*\{\s*"Steam"\s*\{', t, re.I)
        if not m:
            raise RuntimeError(tr("no_mapping"))
        t = t[:m.end()] + '\n\t\t\t\t"CompatToolMapping"\n\t\t\t\t{\n\t\t\t\t}' + t[m.end():]
        i = t.find('"CompatToolMapping"')
    pat = re.compile(r'("%s"\s*\{\s*"name"\s*")[^"]*(")' % appid)
    m = pat.search(t, i)
    if m:
        t = t[:m.start()] + m.group(1) + tool + m.group(2) + t[m.end():]
    else:
        j = t.index("{", i) + 1
        blk = ('\n\t\t\t\t\t"%s"\n\t\t\t\t\t{\n\t\t\t\t\t\t"name"\t\t"%s"\n\t\t\t\t\t\t"config"\t\t""\n'
               '\t\t\t\t\t\t"priority"\t\t"250"\n\t\t\t\t\t}' % (appid, tool))
        t = t[:j] + blk + t[j:]
    shutil.copy2(CFG_VDF, str(CFG_VDF) + ".bak-protonupd")
    CFG_VDF.write_text(t, encoding="utf-8")


def steam_games():
    out = {}
    for f in (STEAM / "steamapps").glob("appmanifest_*.acf"):
        t = f.read_text(errors="ignore")
        n = re.search(r'"name"\s*"([^"]*)"', t)
        if n and not re.search(r"Proton|Steam Linux Runtime|SteamVR|Steamworks", n.group(1)):
            out[f.stem.split("_")[1]] = n.group(1)
    return dict(sorted(out.items(), key=lambda x: x[1].lower()))


# ---------- logic ----------
def notify(msg):
    subprocess.run(["notify-send", "-a", "Proton Updater", "-i", "system-software-update", "Proton", msg],
                   capture_output=True)


def wanted_for(src, game, rels):
    """Which version a game should have: the pinned one or the latest."""
    if game.get("pin"):
        return next((r for r in rels if r["tag"] == game["pin"] or r["name"] == game["pin"]), None)
    return rels[0] if rels else None


def needs_update(appid, g, rel, cur=None):
    """True when a newer Proton than the one the game uses has been released (bell icon).
    Pinned games compare against their pin; the others against the newest release."""
    if not rel:
        return False
    if g.get("pin"):
        return rel["tag"] != g["pin"] and rel["name"] != g["pin"]
    tool = names().get(rel["url"], {}).get("tool") or rel["name"]
    return (cur or current_tool(appid)) != tool


def newer_version(a, b):
    """Is version string a (like 1.3.0 or v1.3.0) newer than b?"""
    num = lambda s: [int(x) for x in re.findall(r"\d+", s)]
    return num(a) > num(b)


def app_update():
    """Newest Proton Updater release that is newer than the running one, else None. Returns (version, page, notes)."""
    r = http_json(f"https://api.github.com/repos/{APP_REPO}/releases/latest")
    tag = r.get("tag_name", "")
    if tag and newer_version(tag, VERSION):
        return {"version": tag.lstrip("v"), "tag": tag, "page": r.get("html_url", ""), "notes": r.get("body") or ""}
    return None


def update_self(info, log=print):
    """Download the new release of this program from GitHub and run its installer."""
    with tempfile.TemporaryDirectory() as tmp:
        f = Path(tmp) / "a.tar.gz"
        url = f"https://codeload.github.com/{APP_REPO}/tar.gz/refs/tags/{info['tag']}"
        log(tr("dl", name=f"Proton Updater {info['version']}", mb=1))
        req = urllib.request.Request(url, headers={"User-Agent": "proton-updater"})
        with urllib.request.urlopen(req, timeout=60) as r, open(f, "wb") as o:
            shutil.copyfileobj(r, o)
        with tarfile.open(f) as t:
            t.extractall(tmp, filter="data")
        d = next(x for x in Path(tmp).iterdir() if x.is_dir())
        res = subprocess.run(["bash", str(d / "install.sh")], capture_output=True, text=True)
        if res.returncode:
            raise RuntimeError(res.stderr.strip() or res.stdout.strip())
    log(tr("self_updated", v=info["version"]))


def tool_present(tool):
    """Is a tool with this Steam name installed? (the folder name may differ for custom sources)"""
    return (COMPAT / tool).exists() or any(v["tool"] == tool and (COMPAT / v["dir"]).exists() for v in names().values())


def apply_pending(c, log=print):
    if not c["pending"]:
        return
    if steam_running():
        return
    for appid, tool in list(c["pending"].items()):
        if tool_present(tool):
            set_tool(appid, tool)
            gname = c["games"].get(appid, {}).get("name", appid)
            log(tr("switched", game=gname, tool=tool))
            notify(tr("notify_switched", game=gname, tool=tool))
        del c["pending"][appid]
    save(c)


def game_running():
    return subprocess.run(["pgrep", "-f", "reaper SteamLaunch"], capture_output=True).returncode == 0


def restart_steam(c, log=print):
    """Close Steam, apply pending switches, start Steam again."""
    if game_running():
        raise RuntimeError(tr("game_running"))
    if steam_running():
        log(tr("closing_steam"))
        subprocess.run(["steam", "-shutdown"], capture_output=True)
        for _ in range(90):
            if not steam_running():
                break
            time.sleep(1)
        else:
            raise RuntimeError(tr("steam_no_close"))
        time.sleep(2)
    apply_pending(c, log)
    log(tr("starting_steam"))
    subprocess.Popen(["steam"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, start_new_session=True)


def auto_enabled(c, g):
    """Does this game get new Proton versions installed automatically in the background?"""
    return bool(c.get("auto_global", True)) and g.get("auto", True) and not g.get("pin")


def check(c, log=print, background=False):
    """Look for new releases. Installs/queues the switch for games that want it:
    - automatic games (global switch on + the game's own switch on) always;
    - pinned games get their pinned version (manual check only, or background if the global switch is on);
    - games with auto-update OFF only get a bell + notification.
    background=True is the timer: it obeys the global switch."""
    cache = {}
    for appid, g in c["games"].items():
        src = g["source"]
        if src not in cache:
            cache[src] = releases(src)
        newest = cache[src][0] if cache[src] else None
        wants = g.get("auto", True) or bool(g.get("pin"))
        if background and not c.get("auto_global", True):
            wants = False
        if not wants or (not g.get("pin") and not g.get("auto", True)):
            if newest and needs_update(appid, g, newest):
                log(tr("log_off_new", game=g["name"], ver=newest["name"]))
                if c["bell"].get(appid) != newest["tag"]:
                    notify(tr("notify_pin_new", game=g["name"], ver=newest["name"]))  # bell: stays on current version
                    c["bell"][appid] = newest["tag"]
            else:
                log(tr("log_off_ok", game=g["name"], cur=current_tool(appid) or "—"))
            continue
        if newest and g.get("pin") and needs_update(appid, g, newest) and c["bell"].get(appid) != newest["tag"]:
            notify(tr("notify_pin_new", game=g["name"], ver=newest["name"]))
            c["bell"][appid] = newest["tag"]
        rel = wanted_for(src, g, cache[src])
        if not rel:
            log(tr("log_norel", game=g["name"]))
            continue
        tool = install(rel, log, src if SOURCES[src].get("custom") else None)
        if current_tool(appid) != tool:
            c["pending"][appid] = tool
            log(tr("log_new", game=g["name"], ver=tool))
        elif g.get("pin"):
            log(tr("log_pin_ok", game=g["name"], ver=tool))
        else:
            log(tr("log_ok", game=g["name"], cur=tool))
    c["last_check"] = time.time()
    save(c)
    cleanup(c, log)
    if c["pending"] and steam_running():
        notify(tr("notify_ready"))


def check_app(log=print):
    """Log whether a newer Proton Updater exists (never raises)."""
    try:
        u = app_update()
        log(tr("log_app_new", v=u["version"], cur=VERSION) if u else tr("log_app_ok", v=VERSION))
        return u
    except Exception as e:
        log(tr("log_app_fail", e=e))


def update_game(c, appid, log=print):
    """'Update now' for one game: install its newest release and queue the switch (ignores the auto-update switch)."""
    g = c["games"][appid]
    rels = releases(g["source"])
    if not rels:
        return
    tool = install(rels[0], log, g["source"] if SOURCES[g["source"]].get("custom") else None)
    g["pin"] = None
    if current_tool(appid) != tool:
        c["pending"][appid] = tool
    c["bell"].pop(appid, None)
    save(c)
    if c["pending"] and steam_running():
        notify(tr("notify_ready"))


def cleanup(c, log=print):
    used = {current_tool(a) for a in c["games"]} | set(c["pending"].values())
    for src, s in SOURCES.items():
        if s.get("custom"):
            mine = sorted(((v["dir"], v["tool"]) for v in names().values() if v["src"] == src),
                          key=lambda x: (COMPAT / x[0]).stat().st_mtime if (COMPAT / x[0]).exists() else 0, reverse=True)
            mine = [m for m in dict(mine).items() if (COMPAT / m[0]).exists()]
            for d, tool in mine[c["keep"]:]:
                if tool not in used:
                    shutil.rmtree(COMPAT / d, ignore_errors=True)
                    log(tr("removed_old", name=d))
            continue
        have = [n for s, n in installed(src)]
        have.sort(key=lambda n: [int(x) if x.isdigit() else 0 for x in re.split(r"\D+", n)], reverse=True)
        keep = set(have[:c["keep"]]) | used
        for n in have:
            if n not in keep:
                shutil.rmtree(COMPAT / n, ignore_errors=True)
                log(tr("removed_old", name=n))


def run():
    c = load()
    apply_pending(c)
    if time.time() - c["last_check"] > 12 * 3600:
        try:
            check(c, background=True)
        except Exception as e:
            print(tr("check_failed", e=e), file=sys.stderr)
        apply_pending(c)
    try:
        u = app_update()
        if u and c.get("notified_app") != u["version"]:
            notify(tr("notify_app_new", v=u["version"]))
            c["notified_app"] = u["version"]; save(c)
    except Exception:
        pass


def main(a):
    cmd = a[0] if a else "status"
    c = load()
    if cmd == "run":
        run()
    elif cmd == "check":
        check(c); apply_pending(c); check_app()
    elif cmd == "restart":
        restart_steam(c)
    elif cmd == "auto":
        if len(a) < 2 or a[1] not in ("on", "off"):
            print("usage: proton-updater auto on|off [APPID]"); return
        if len(a) > 2:
            c["games"][a[2]]["auto"] = a[1] == "on"
        else:
            c["auto_global"] = a[1] == "on"
        save(c); print(a[1])
    elif cmd == "version":
        print(f"Proton Updater {VERSION}")
        u = app_update()
        print(tr("app_new_title", v=u["version"]) if u else tr("app_latest"))
    elif cmd == "selfupdate":
        u = app_update()
        update_self(u) if u else print(tr("app_latest"))
    elif cmd == "status":
        for appid, g in c["games"].items():
            print(tr("status_line", name=g["name"], appid=appid, src=g["source"], cur=current_tool(appid),
                     pin=g.get("pin") or tr("no"), pend=c["pending"].get(appid, "-")))
        print(tr("installed_list", l=", ".join(n for _, n in installed())))
    elif cmd == "install":
        rel = next(r for r in releases(a[1], 100) if r["tag"] == a[2] or r["name"] == a[2])
        install(rel, src=a[1] if SOURCES[a[1]].get("custom") else None)
    elif cmd == "set":
        appid, src = a[1], a[2]
        c["games"][appid] = {"name": steam_games().get(appid, appid), "source": src, "pin": a[3] if len(a) > 3 else None}
        save(c)
    else:
        print(__doc__)


if __name__ == "__main__":
    main(sys.argv[1:])
